import { readFileSync, writeFileSync } from 'node:fs';
// Keep one editable CSS source; embed it so it can be restored after Docs replaces its head.
const css = readFileSync(new URL('./compact.css', import.meta.url), 'utf8');
writeFileSync(new URL('./styles.js', import.meta.url),
  '// Generated by node build-styles.mjs. Edit compact.css.\nconst COMPACTDOCS_CSS = ' + JSON.stringify(css) + ';\n');
